int **sum_of_2_dim_arrays(int **A, int *SA, int **B, int *SB, int **SC,
int n)
{
      int i, j, **C;
      C = (int **)calloc(n, sizeof(int *));
      *SC = (int *)calloc(n, sizeof(int));
      for (i=0; i<n; i++) {
            (*SC)[i] = (SA[i]<SB[i])? SA[i] : SB[i];
            C[i] = (int *)calloc((*SC)[i], sizeof(int));
            for (j=0; j<(*SC)[i]; j++)
                  C[i][j] = A[i][j]+B[i][j];
      }
      return C;
}
